.af {--gold: #e8c37a;--ink: #e9edf4;--dim: #9db0c6;position: relative;width: 100%;max-width: 640px;margin: 6px auto;container-type: inline-size;border-radius: 14px;overflow: hidden;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;color: var(--ink);background: linear-gradient(165deg, #16213a 0%, #0d1526 40%, #0a0f1d 100%);box-shadow: 0 10px 34px #0d1420aa, inset 0 0 0 1px #ffffff12;}
.af::before {content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(1px 1px at 12% 18%, #fff8 50%, transparent 51%), radial-gradient(1px 1px at 78% 8%, #fff6 50%, transparent 51%), radial-gradient(1.5px 1.5px at 55% 22%, #ffd9a05e 50%, transparent 51%), radial-gradient(1px 1px at 30% 30%, #fff5 50%, transparent 51%), radial-gradient(1px 1px at 90% 26%, #fff4 50%, transparent 51%), radial-gradient(1.5px 1.5px at 68% 15%, #fff5 50%, transparent 51%);}
.af::after {content: ""; position: absolute; left: -10%; right: -10%; bottom: -14%; height: 34%; pointer-events: none; background: radial-gradient(ellipse 60% 100% at 30% 100%, #0e1930 0%, transparent 70%), radial-gradient(ellipse 70% 100% at 75% 100%, #0b1322 0%, transparent 70%);}
.af-head {position: relative; z-index: 2; padding: 5.4cqw 0 3cqw; text-align: center; border-bottom: 1px solid #ffffff10; background: linear-gradient(#ffffff08, transparent);}
.af-eyebrow {font-size: 2.2cqw; letter-spacing: .34em; color: var(--gold); opacity: .85;}
.af-title {display: block; font-size: 6.4cqw; letter-spacing: .5em; text-indent: .5em; margin: 1.2cqw 0 .8cqw; color: var(--ink); text-shadow: 0 0 18px #e8c37a33;}
.af-subtitle {font-size: 2.3cqw; letter-spacing: .2em; color: var(--dim);}
.af-cards {position: relative; z-index: 2; display: flex; gap: 2.6cqw; padding: 4cqw 3.4cqw 4.4cqw;}
.af-card {flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 1.2cqw; padding: 3.4cqw 2cqw 3cqw; border-radius: 12px; background: #ffffff07; border: 1px solid #ffffff10; position: relative; transition: transform .5s;}
.af-card.is-on {background: linear-gradient(#ffffff0d, #ffffff04); border-color: #ffffff1c; box-shadow: 0 8px 26px #0006, inset 0 1px 0 #ffffff1a;}
.af-card.is-max {border-color: #e8c37a66; box-shadow: 0 0 30px #e8c37a22, inset 0 1px 0 #ffffff1a;}
.af-card.is-off {opacity: .5; filter: saturate(.3);}
.af-card.is-off:hover {opacity: .75;}
.af-ring {position: relative; width: 24cqw; height: 24cqw; max-width: 118px; max-height: 118px;}
.af-ring svg {position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg);}
.af-ring-bg {fill: none; stroke: #ffffff14; stroke-width: 5;}
.af-ring-fg {fill: none; stroke: var(--ac); stroke-width: 5; stroke-linecap: round; stroke-dasharray: 276.46; stroke-dashoffset: 276.46; filter: drop-shadow(0 0 4px var(--ac));}
.af-ava {position: absolute; inset: 9%; width: 82%; height: 82%; border-radius: 50%; object-fit: cover; border: 1px solid #ffffff2e; background: #0d1526;}
.af-card.is-max .af-ava {border-color: var(--gold); animation: afGlow 2.4s ease-in-out infinite;}
@keyframes afGlow {50% { box-shadow: 0 0 18px #e8c37ab3; }}
.af-num {position: absolute; left: 0; right: 0; bottom: -8%; text-align: center; font-size: 4.6cqw; font-weight: 700; color: var(--ink); text-shadow: 0 1px 6px #000b; font-variant-numeric: tabular-nums;}
.af-num::after {content: " /100"; font-size: 2cqw; font-weight: 400; color: var(--dim);}
.af-name {font-size: 3.8cqw; margin-top: 2.4cqw; color: var(--ink); letter-spacing: .14em;}
.af-sub {font-style: normal; font-size: 2.1cqw; color: var(--dim); letter-spacing: .12em;}
.af-lv {font-size: 2.4cqw; letter-spacing: .14em; padding: .9cqw 2.4cqw; border-radius: 999px; color: #0d1420; background: var(--lvc); font-weight: 700; box-shadow: 0 2px 10px #0006;}
.af-card.is-max .af-lv {background: linear-gradient(135deg, #f2d493, #d9a94f); animation: afPulse 2.4s ease-in-out infinite;}
@keyframes afPulse {50% { box-shadow: 0 0 16px #e8c37a88; }}
.af-bar {position: relative; width: 100%; height: 3.4cqw; border-radius: 999px; background: linear-gradient(#2b3242, #1a2130); border: 1px solid #ffffff10; overflow: visible; margin-top: 1.2cqw;}
.af-bar::before {content: ""; position: absolute; left: 3%; right: 3%; top: 50%; height: 1px; background: repeating-linear-gradient(90deg, #ffffff45 0 8%, transparent 8% 16%); opacity: .6;}
.af-fill {position: absolute; left: 0; top: 0; bottom: 0; width: 0; border-radius: 999px; background: var(--ac); box-shadow: 0 0 10px var(--ac); transition: width 1.2s cubic-bezier(.22,.9,.3,1); overflow: hidden;}
.af-fill::after {content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(115deg, #ffffff2e 0 .6cqw, transparent .6cqw 1.8cqw); animation: afFlow 1.8s linear infinite;}
@keyframes afFlow {to { transform: translateX(1.8cqw); }}
.af-ms {position: absolute; top: 50%; width: 1.4cqw; height: 1.4cqw; border-radius: 50%; transform: translate(-50%,-50%); background: #0d1420; border: 1px solid #ffffff30;}
.af-ms.is-lit {background: var(--ac); border-color: #fff8; box-shadow: 0 0 6px var(--ac);}
.af-car {position: absolute; top: 50%; transform: translate(-50%,-50%); font-size: 2.6cqw; color: #fff; text-shadow: 0 0 8px var(--ac), 0 0 2px #000; transition: left 1.2s cubic-bezier(.22,.9,.3,1);}
.af-quote {font-size: 2.3cqw; color: var(--dim); text-align: center; line-height: 1.6; margin-top: 1cqw; min-height: 4.6cqw;}
.af-nodata {font-size: 2.4cqw; letter-spacing: .3em; color: #6a7a8e; margin-top: 2.6cqw; padding: .8cqw 2cqw; border-radius: 4px; border: 1px dashed #ffffff22;}
.af-off-quote {font-size: 2.2cqw; color: #5a6a7e; text-align: center; margin-top: .6cqw;}
.af-foot {position: relative; z-index: 2; display: flex; align-items: center; justify-content: center; gap: 2.4cqw; padding: 0 4cqw 3.6cqw;}
.af-foot i {flex: 1; height: 1px; background: linear-gradient(90deg, transparent, #e8c37a55, transparent);}
.af-foot span {font-size: 2.2cqw; letter-spacing: .18em; color: var(--dim); white-space: nowrap;}
